from pathlib import Path
p=Path('components/WorkflowWorkspaceV2.tsx')
s=p.read_text()
old='''{selectedAvailability.length > 0 ? <section className="rounded-2xl border border-[#01A32E] bg-[#01A32E] p-4 shadow-sm">\n              <div className="flex items-center justify-between gap-3"><div><p className="text-xs font-black uppercase tracking-wide text-white">I’m Available</p>{selectedAvailability.map((slot) => <div key={slot.id}><p className="mt-1 text-sm font-black text-white">{shortTime(slot.starts_at)}–{shortTime(slot.ends_at)}</p><p className="mt-0.5 text-xs font-extrabold text-white/90">${Number(slot.hourly_rate).toFixed(2)}/hr</p></div>)}</div><button type="button" disabled={busy === selectedAvailability[0].id} onClick={() => void run(selectedAvailability[0].id, () => removeProfessionalAvailability(selectedAvailability[0].id)).then((removed) => { if (removed) setAvailabilityOpen(true); })} className="secondary-btn">Cancel / Repost</button></div>\n            </section>'''
new='''{selectedAvailability.length > 0 ? <section className="overflow-hidden rounded-2xl border-2 border-[#01A32E] bg-white shadow-sm">\n              <div className="flex items-center gap-2 bg-[#01A32E] px-4 py-2.5"><span className="grid h-6 w-6 place-items-center rounded-full bg-white text-sm font-black text-[#017f27]">✓</span><p className="text-sm font-black tracking-wide text-white">I’m Available</p></div>\n              <div className="flex items-center justify-between gap-3 p-4"><div className="min-w-0 space-y-2">{selectedAvailability.map((slot) => <div key={slot.id} className="flex flex-wrap items-center gap-x-3 gap-y-1"><span className="inline-flex items-center gap-1.5 text-sm font-black text-[#002757]"><Clock3 size={15} className="text-[#017f27]" />{shortTime(slot.starts_at)}–{shortTime(slot.ends_at)}</span><span className="rounded-full bg-[#eaf8ee] px-2.5 py-1 text-xs font-black text-[#017f27]">${Number(slot.hourly_rate).toFixed(2)}/hr</span></div>)}</div><button type="button" disabled={busy === selectedAvailability[0].id} onClick={() => void run(selectedAvailability[0].id, () => removeProfessionalAvailability(selectedAvailability[0].id)).then((removed) => { if (removed) setAvailabilityOpen(true); })} className="secondary-btn shrink-0 border-[#01A32E]/30 text-[#017f27] hover:bg-[#edf9f0]">Cancel / Repost</button></div>\n            </section>'''
if old not in s: raise SystemExit('available card anchor not found')
s=s.replace(old,new,1)
p.write_text(s)
print('Polished professional I’m Available card without changing functionality.')